import React, { useState, useEffect } from 'react';
import { createClient } from '@supabase/supabase-js';
import io from 'socket.io-client';

const supabase = createClient(
    'https://ixikhufrylaugpdxokwu.supabase.co',
    'sb_publishable_7T38wLjTEs7UJKMMTxl9tQ_OLM6Wsf3'
);

const StaffDashboard = ({ clinicId, staffId, staffName }) => {
    const [queue, setQueue] = useState([]);
    const [summary, setSummary] = useState({
        total_waiting: 0,
        in_consultation_count: 0,
        completed_today: 0,
        average_wait_minutes: 0
    });
    const [socket, setSocket] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    
    useEffect(() => {
        const newSocket = io('http://localhost:3001', {
            auth: { userId: staffId, role: 'staff', clinicId }
        });
        setSocket(newSocket);
        
        newSocket.on('queue:updated', () => {
            console.log('Real-time update received - refreshing data...');
            fetchQueueFromDB();
            fetchSummary();
        });
        
        fetchQueueFromDB();
        fetchSummary();
        
        return () => newSocket.close();
    }, [clinicId]);
    
    // const fetchQueueFromDB = async () => {
    //     try {
    //         setLoading(true);
            
    //         // Get ALL active appointments (not just today's date)
    //         // Show waiting and in_consultation regardless of date
    //         const { data, error } = await supabase
    //             .from('Appointments')
    //             .select('*')
    //             .in('status', ['waiting', 'in_consultation'])
    //             .order('arrived_at', { ascending: true });
            
    //         if (error) {
    //             console.error('Supabase error:', error);
    //             setError(error.message);
    //             setLoading(false);
    //             return;
    //         }
            
    //         console.log('Fetched appointments:', data);
    //         console.log('Total active appointments:', data?.length);
            
    //         if (!data || data.length === 0) {
    //             console.log('No active appointments found');
    //             setQueue([]);
    //             setLoading(false);
    //             return;
    //         }
            
    //         // Filter by clinicId if provided
    //         const filteredData = clinicId 
    //             ? data.filter(item => item.ClinicID === clinicId)
    //             : data;
            
    //         console.log('Filtered by clinic:', filteredData.length);
            
    //         // Format the queue data
    //         const formattedQueue = filteredData.map((item, idx) => {
    //             let waitMinutes = 0;
    //             if (item.arrived_at) {
    //                 const arrived = new Date(item.arrived_at);
    //                 const now = new Date();
    //                 waitMinutes = Math.floor((now - arrived) / 60000);
    //             }
                
    //             return {
    //                 appointment_id: item.id,
    //                 queue_position: idx + 1,
    //                 patient_name: item.patient_name,
    //                 waiting_minutes: waitMinutes,
    //                 patient_status: item.status,
    //                 is_walk_in: item.is_walk_in || false,
    //                 arrived_at: item.arrived_at,
    //                 clinic_id: item.ClinicID,
    //                 appointment_date: item.appointment_date
    //             };
    //         });
            
    //         setQueue(formattedQueue);
    //         setError(null);
    //     } catch (err) {
    //         console.error('Error in fetchQueueFromDB:', err);
    //         setError(err.message);
    //     } finally {
    //         setLoading(false);
    //     }
    // };
    const fetchQueueFromDB = async () => {
    try {
        setLoading(true);
        
        // Get ALL active appointments (waiting or in consultation)
        const { data, error } = await supabase
            .from('Appointments')
            .select('*')
            .in('status', ['waiting', 'in_consultation'])
            .order('arrived_at', { ascending: true });
        
        if (error) {
            console.error('Supabase error:', error);
            setError(error.message);
            setLoading(false);
            return;
        }
        
        console.log('Fetched appointments:', data);
        
        if (!data || data.length === 0) {
            setQueue([]);
            setLoading(false);
            return;
        }
        
        // Filter by clinicId if provided
        const filteredData = clinicId 
            ? data.filter(item => item.ClinicID === clinicId)
            : data;
        
        // Format the queue data with BETTER wait time display
        const now = new Date();
        const formattedQueue = filteredData.map((item, idx) => {
            let waitMinutes = 0;
            let waitDisplay = '';
            let waitColor = 'inherit';
            
            if (item.arrived_at) {
                const arrived = new Date(item.arrived_at);
                waitMinutes = Math.floor((now - arrived) / 60000);
                
                // Format wait time nicely (e.g., "1h 30m" instead of just "90 min")
                if (waitMinutes < 60) {
                    waitDisplay = `${waitMinutes} min`;
                } else {
                    const hours = Math.floor(waitMinutes / 60);
                    const mins = waitMinutes % 60;
                    waitDisplay = `${hours}h ${mins}m`;
                }
                
                // Color code based on wait time
                if (waitMinutes > 60) {
                    waitColor = '#dc2626'; // Red for > 1 hour (urgent)
                } else if (waitMinutes > 30) {
                    waitColor = '#f59e0b'; // Orange for > 30 min
                } else if (waitMinutes > 15) {
                    waitColor = '#eab308'; // Yellow for > 15 min
                } else {
                    waitColor = '#10b981'; // Green for < 15 min (good)
                }
            }
            
            return {
                appointment_id: item.id,
                queue_position: idx + 1,
                patient_name: item.patient_name,
                waiting_minutes: waitMinutes,
                wait_display: waitDisplay,
                wait_color: waitColor,
                patient_status: item.status,
                is_walk_in: item.is_walk_in || false,
                arrived_at: item.arrived_at,
                arrived_time: item.arrived_at ? new Date(item.arrived_at).toLocaleTimeString() : 'Unknown',
                clinic_id: item.ClinicID
            };
        });
        
        setQueue(formattedQueue);
        setError(null);
    } catch (err) {
        console.error('Error in fetchQueueFromDB:', err);
        setError(err.message);
    } finally {
        setLoading(false);
    }
};
    
    const fetchSummary = async () => {
        try {
            // Get all appointments for stats
            const { data, error } = await supabase
                .from('Appointments')
                .select('status, actual_wait_seconds, ClinicID');
            
            if (error) {
                console.error('Error fetching summary:', error);
                return;
            }
            
            if (!data) return;
            
            // Filter by clinic if needed
            const filteredData = clinicId 
                ? data.filter(item => item.ClinicID === clinicId)
                : data;
            
            const waiting = filteredData.filter(a => a.status === 'waiting').length;
            const inConsultation = filteredData.filter(a => a.status === 'in_consultation').length;
            const completed = filteredData.filter(a => a.status === 'complete').length;
            
            // Calculate average wait time
            const completedWithWait = filteredData.filter(a => a.status === 'complete' && a.actual_wait_seconds);
            let avgWait = 15;
            if (completedWithWait.length > 0) {
                const totalWait = completedWithWait.reduce((sum, a) => sum + (a.actual_wait_seconds || 0), 0);
                avgWait = Math.round(totalWait / completedWithWait.length / 60);
            }
            
            setSummary({
                total_waiting: waiting,
                in_consultation_count: inConsultation,
                completed_today: completed,
                average_wait_minutes: avgWait
            });
        } catch (err) {
            console.error('Error in fetchSummary:', err);
        }
    };
    
    const updateStatus = async (appointmentId, newStatus) => {
        try {
            const updateData = { status: newStatus };
            if (newStatus === 'in_consultation') {
                updateData.consultation_started_at = new Date().toISOString();
            }
            if (newStatus === 'complete') {
                updateData.consultation_ended_at = new Date().toISOString();
                // Calculate actual wait time
                const appointment = queue.find(a => a.appointment_id === appointmentId);
                if (appointment && appointment.arrived_at) {
                    const arrived = new Date(appointment.arrived_at);
                    const now = new Date();
                    updateData.actual_wait_seconds = Math.floor((now - arrived) / 1000);
                }
            }
            
            const { error } = await supabase
                .from('Appointments')
                .update(updateData)
                .eq('id', appointmentId);
            
            if (error) {
                console.error('Error updating status:', error);
                alert('Error updating status: ' + error.message);
                return;
            }
            
            await fetchQueueFromDB();
            await fetchSummary();
            
            if (socket) {
                socket.emit('status:update', {
                    appointmentId,
                    newStatus,
                    staffId,
                    clinicId
                });
            }
            
            console.log(`Status updated to ${newStatus} for appointment ${appointmentId}`);
        } catch (err) {
            console.error('Error in updateStatus:', err);
            alert('Error updating status');
        }
    };
    
    const addTestPatient = async () => {
        const newPatientName = 'Test Patient ' + Math.floor(Math.random() * 100);
        const now = new Date();
        const timeStr = now.toTimeString().split(' ')[0];
        
        try {
            const { error } = await supabase
                .from('Appointments')
                .insert({
                    id: crypto.randomUUID(),
                    patient_name: newPatientName,
                    ClinicID: clinicId,
                    appointment_date: now.toISOString().split('T')[0],
                    appointment_time: timeStr,
                    status: 'waiting',
                    is_walk_in: false,
                    arrived_at: now.toISOString()
                });
            
            if (error) {
                console.error('Error adding test patient:', error);
                alert('Error: ' + error.message);
            } else {
                alert('Test patient added: ' + newPatientName);
                await fetchQueueFromDB();
                await fetchSummary();
            }
        } catch (err) {
            console.error('Error:', err);
            alert('Error adding patient');
        }
    };
    
    if (loading) {
        return (
            <div style={{ padding: '40px', textAlign: 'center' }}>
                <h2>Loading Dashboard...</h2>
                <p>Fetching data from database...</p>
            </div>
        );
    }
    
    if (error) {
        return (
            <div style={{ padding: '40px', textAlign: 'center', color: 'red' }}>
                <h2>Error Loading Data</h2>
                <p>{error}</p>
                <button 
                    onClick={() => window.location.reload()}
                    style={{ padding: '10px 20px', marginTop: '20px', cursor: 'pointer' }}
                >
                    Retry
                </button>
            </div>
        );
    }
    
    return (
        <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
                <div>
                    <h1>🏥 Clinic Queue Management Dashboard</h1>
                    <p>Welcome, {staffName || 'Staff Member'}</p>
                    <p>📍 Active Clinic: {clinicId || 'All Clinics'}</p>
                    <p style={{ fontSize: '12px', color: '#666' }}>
                        Showing all patients with status: Waiting or In Consultation
                    </p>
                </div>
                <button 
                    onClick={addTestPatient}
                    style={{
                        background: '#6366f1',
                        color: 'white',
                        border: 'none',
                        padding: '10px 20px',
                        borderRadius: '6px',
                        cursor: 'pointer',
                        fontSize: '14px'
                    }}
                >
                    + Add Test Patient
                </button>
            </div>
            
            {/* Stats Cards */}
            <div style={{ 
                display: 'grid', 
                gridTemplateColumns: 'repeat(4, 1fr)', 
                gap: '15px', 
                margin: '20px 0' 
            }}>
                <div style={{ padding: '20px', background: '#fef3c7', borderRadius: '8px', borderLeft: '4px solid #f59e0b' }}>
                    <div style={{ fontSize: '14px', color: '#92400e' }}>🕐 Waiting</div>
                    <div style={{ fontSize: '32px', fontWeight: 'bold', color: '#92400e' }}>{summary.total_waiting}</div>
                </div>
                <div style={{ padding: '20px', background: '#d1fae5', borderRadius: '8px', borderLeft: '4px solid #10b981' }}>
                    <div style={{ fontSize: '14px', color: '#065f46' }}>💚 In Consultation</div>
                    <div style={{ fontSize: '32px', fontWeight: 'bold', color: '#065f46' }}>{summary.in_consultation_count}</div>
                </div>
                <div style={{ padding: '20px', background: '#dbeafe', borderRadius: '8px', borderLeft: '4px solid #3b82f6' }}>
                    <div style={{ fontSize: '14px', color: '#1e3a8a' }}>✅ Completed</div>
                    <div style={{ fontSize: '32px', fontWeight: 'bold', color: '#1e3a8a' }}>{summary.completed_today}</div>
                </div>
                <div style={{ padding: '20px', background: '#e9d5ff', borderRadius: '8px', borderLeft: '4px solid #8b5cf6' }}>
                    <div style={{ fontSize: '14px', color: '#4c1d95' }}>⏱️ Avg Wait Time</div>
                    <div style={{ fontSize: '32px', fontWeight: 'bold', color: '#4c1d95' }}>{summary.average_wait_minutes} min</div>
                </div>
            </div>
            
            {/* Queue Table */}
            <div style={{ background: 'white', borderRadius: '8px', border: '1px solid #e5e7eb', overflow: 'hidden' }}>
                <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                    <thead>
                        <tr style={{ background: '#f9fafb', borderBottom: '1px solid #e5e7eb' }}>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Position</th>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Patient Name</th>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Wait Time</th>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Type</th>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Clinic ID</th>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Status</th>
                            <th style={{ padding: '12px', textAlign: 'left' }}>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {queue.map((patient) => (
                            <tr key={patient.appointment_id} style={{ borderBottom: '1px solid #e5e7eb' }}>
                                <td style={{ padding: '12px', fontWeight: 'bold' }}>{patient.queue_position}</td>
                                <td style={{ padding: '12px' }}>{patient.patient_name}</td>
                                <td style={{ padding: '12px' }}>
                                    <span style={{ fontWeight: patient.waiting_minutes > 30 ? 'bold' : 'normal', color: patient.waiting_minutes > 30 ? 'red' : 'inherit' }}>
                                        {patient.waiting_minutes} min
                                    </span>
                                </td>
                                <td style={{ padding: '12px' }}>
                                    <span style={{
                                        padding: '2px 8px',
                                        borderRadius: '12px',
                                        fontSize: '12px',
                                        background: patient.is_walk_in ? '#fed7aa' : '#bfdbfe',
                                        color: patient.is_walk_in ? '#9a3412' : '#1e40af'
                                    }}>
                                        {patient.is_walk_in ? 'Walk-in' : 'Scheduled'}
                                    </span>
                                </td>
                                <td style={{ padding: '12px', fontSize: '12px' }}>
                                    {patient.clinic_id}
                                </td>
                                <td style={{ padding: '12px' }}>
                                    <span style={{
                                        padding: '4px 8px',
                                        borderRadius: '20px',
                                        fontSize: '12px',
                                        background: patient.patient_status === 'waiting' ? '#fef3c7' : '#d1fae5',
                                        color: patient.patient_status === 'waiting' ? '#92400e' : '#065f46'
                                    }}>
                                        {patient.patient_status === 'waiting' ? '🕐 Waiting' : '💚 In Consultation'}
                                    </span>
                                </td>
                                <td style={{ padding: '12px' }}>
                                    {patient.patient_status === 'waiting' && (
                                        <button 
                                            onClick={() => updateStatus(patient.appointment_id, 'in_consultation')}
                                            style={{
                                                background: '#10b981',
                                                color: 'white',
                                                border: 'none',
                                                padding: '8px 16px',
                                                borderRadius: '6px',
                                                cursor: 'pointer',
                                                fontSize: '12px'
                                            }}
                                        >
                                            Start Consultation
                                        </button>
                                    )}
                                    {patient.patient_status === 'in_consultation' && (
                                        <button 
                                            onClick={() => updateStatus(patient.appointment_id, 'complete')}
                                            style={{
                                                background: '#3b82f6',
                                                color: 'white',
                                                border: 'none',
                                                padding: '8px 16px',
                                                borderRadius: '6px',
                                                cursor: 'pointer',
                                                fontSize: '12px'
                                            }}
                                        >
                                            Complete
                                        </button>
                                    )}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
            
            {queue.length === 0 && (
                <div style={{ textAlign: 'center', padding: '40px', color: '#6b7280' }}>
                    <p>No active patients in queue.</p>
                    <p style={{ fontSize: '14px', marginTop: '10px' }}>
                        Patients with status "waiting" or "in_consultation" will appear here.
                    </p>
                    <button 
                        onClick={addTestPatient}
                        style={{
                            background: '#6366f1',
                            color: 'white',
                            border: 'none',
                            padding: '10px 20px',
                            borderRadius: '6px',
                            cursor: 'pointer',
                            marginTop: '20px'
                        }}
                    >
                        Add your first test patient
                    </button>
                </div>
            )}
            
            <details style={{ marginTop: '20px', padding: '10px', background: '#f3f4f6', borderRadius: '8px' }}>
                <summary style={{ cursor: 'pointer', fontWeight: 'bold' }}>Debug Info</summary>
                <pre style={{ fontSize: '12px', marginTop: '10px', overflow: 'auto' }}>
                    Active Queue: {queue.length} patients
                    Waiting: {summary.total_waiting}
                    In Consultation: {summary.in_consultation_count}
                    Completed: {summary.completed_today}
                    
                    Raw queue data:
                    {JSON.stringify(queue.map(p => ({
                        name: p.patient_name,
                        status: p.patient_status,
                        wait: p.waiting_minutes,
                        clinic: p.clinic_id
                    })), null, 2)}
                </pre>
            </details>
        </div>
    );
};

export default StaffDashboard;
